import re


from moler.exceptions import ParsingDone, CommandFailure

from ta_moler.cmd.rtg.rtg.genericrtg import GenericRtg

__author__ = 'Dariusz Rosinski, Dawid Gwizdz'
__copyright__ = 'Copyright (C) 2019, Nokia'
__email__ = 'dariusz.rosinski@nokia.com, dawid.gwizdz@gmail.com'


class ConfigRemoteRestart(GenericRtg):
    """Command for restarting RTG components."""

    def __init__(self, connection, target, prompt=None, newline_chars=None,
                 runner=None):
        """
        Config remote restart <target> command.

        :param connection: moler connection to device, terminal when command is executed.
        :param target: what part of rtg system need to be rebooted
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(ConfigRemoteRestart, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.target = target
        self.current_ret['rebooted_devices'] = set()
        # we assume command is successful if no error detected
        self.error = ''
        self.error_start_found = False
        self.parsing_error = False

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "config remote restart"
        cmd = f"{cmd} {self.target}"
        return cmd

    # Example line: ERROR: Execution of remote '/etc/init.d/rtg-tgr restart' failed with code 1, output:
    _re_error_parsing_need = re.compile(r'output:\s*$')

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_error(line)
                self._parse_successfully_restarted(line)
            except ParsingDone:
                pass

        return super(ConfigRemoteRestart, self).on_new_line(line, is_full_line)
    # Example line:
    _re_empty_line = re.compile(r'^\s*$')
    # Example line: |t1|[tgr_1] RETURN CODE: 0
    _re_device_restarted = re.compile(r'\[(?P<TARGET>\w+)\]\s+RETURN CODE: 0')

    def _parse_successfully_restarted(self, line):
        """
        Start command.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(ConfigRemoteRestart._re_empty_line, line):
            raise ParsingDone
        else:
            target = self._regex_helper.search(ConfigRemoteRestart._re_device_restarted, line)
            if target:
                self.current_ret['rebooted_devices'].add(target.group("TARGET"))

    # Example line: ERROR: Execution of remote '/etc/init.d/rtg-tgr restart' failed with code 1
    _re_error = re.compile(r'ERROR:\s*(?P<ERROR>.*)$')
    # Example line: Invalid target specs: wrong
    _re_invalid_target = re.compile(r'Invalid target specs:\s*(?P<TARGET>.*)$')

    def _parse_error(self, line):
        """
        Start command.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        # wrong target specified
        if self._regex_helper.search(self._re_invalid_target, line):
            self.error = f"Invalid Target: {self._regex_helper.group('TARGET')}\n"
            self.set_exception(CommandFailure(self, f"Invalid Target: {self._regex_helper.group('TARGET')}"))
            raise ParsingDone
        # found error
        if self._regex_helper.search(ConfigRemoteRestart._re_error, line):
            self.error = f"{self._regex_helper.group('ERROR')}\n"
            self.set_exception(CommandFailure(self, f"ERROR: {self.error}"))
            raise ParsingDone


